/* ============================================================
   14. 图片与表情包尺寸约束
   ============================================================ */

.msg-image-wrapper,
.msg-image-wrapper img {
  max-width: 220px !important;
  max-height: 280px !important;
  border-radius: 10px !important;
  object-fit: cover !important;
