  --custom-placeholder-color: #9ea4ad;              /* 占位提示词 (message) 颜色 */
  --custom-sticker-icon-color: #7b7e84;             /* 右侧三杠图标：中性冷石灰 */
  --custom-action-box-size: 38px;                   /* 外置按钮尺寸 */
  --custom-action-border: #dce0e6;                  /* 外置按钮边框细线 */
  --custom-action-radius: 12px;                     /* 外置按钮圆角 */
  --custom-action-bg: var(--c-main-bg);             /* 发送键/动作键背景底色：融入大底 */
  --custom-action-icon-color: #7b7e84;              /* 外置按钮内部图标 (箭头/方块) 颜色 */

  /* ── 模块 3：聊天消息区域色彩与配置 ── */
  --msg-font-size: 12px;                            /* ❎❎气泡文字字号 */
  --msg-font-size-sub: 11px;                        /* 辅助/次要文字字号 */
  --msg-font-size-quote: 10.5px;                    /* 引用文字字号 */
  --msg-bubble-padding: 5px 8px;                    /* 气泡内边距 */
  --c-text-main: #2c3038;                           /* 正文字体：纯正冷墨灰，字迹清晰 */
  --c-text-muted: #6c727d;                          /* 翻译/引用副文字：细腻钢笔灰 */

  /* 我方气泡：指定微灰冷白 + 清透浅银描边 (彻底无阴影) */
  --c-me-bg: #ffffff;                               /* 我方气泡底色：细腻微灰白纸色 */
  --c-me-border: #d0d4db;                           /* 我方气泡描边：中性质感浅细线 */

  /* 对方气泡：两层极简纯净灰阶 (首条深锚定，后续全浅收拢，告别混乱与脏感) */

--c-ai-step-1: #ebedf2;        /* 首条：比后续只深一点点，干净冷灰 */
--c-ai-step-follow: #f2f4f7;   /* 后续：直接用你方气泡的颜色 */

  /* 辅助与杂项控制 */
  --translation-always-show: 1;
  --translation-btn-display: none;
  --voice-download-display: none;
  --nq-avatar-border: #e5e5e5;                     /* 头像内描边 */
}

/* ==========================================================================
   第一部分：顶部导航 (Header)
   ========================================================================== */

/* 顶部容器外层：只在聊天界面生效 */
.glass-header:has(.header-profile-section) {
  background: var(--header-bg) !important;
  backdrop-filter: blur(var(--header-blur)) !important;
  -webkit-backdrop-filter: blur(var(--header-blur)) !important;
  border-bottom: var(--header-border-bottom) !important;
  box-shadow: none !important;
  height: var(--header-total-height) !important;
  position: relative !important;
  display: flex !important;
  align-items: flex-start !important;
  padding-top: calc(env(safe-area-inset-top, 44px) + 2px) !important; /*  整体上下位置：+2px 越大越往下，越小/负数越往上 */
  padding-left: 12px !important; /*  整体左右位置：12px 越大越往右 */
  padding-right: 14px !important; /*  整体右侧留白：14px */
  box-sizing: border-box !important;
}

/* 隐藏原生的聊天角色小头像 */
.glass-header:has(.header-profile-section) .header-avatar-container,
.glass-header:has(.header-profile-section) .chat-header-avatar {
  display: none !important;
}

/* 返回按钮：换用自定义矢量 Mask 图标 */
.glass-header:has(.header-profile-section) .header-btn-back {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;
  transform: translate(8px, 2px) !important; /* ❎ 返回键位置：第一个数8px=左右(越大越右)，第二个数2px=上下(越大越下，负数往上) */
  cursor: pointer !important;
}

/* 隐藏返回键自带的 SVG */
.glass-header:has(.header-profile-section) .header-btn-back svg {
  display: none !important;
}

/* 载入细线条冷灰返回键箭头 */
.glass-header:has(.header-profile-section) .header-btn-back::before {
  content: "" !important;
  display: block !important;
  width: 22px !important;
  height: 22px !important;
  background-color: var(--header-text-main) !important;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  -webkit-mask-position: center;
  mask-position: center;
  -webkit-mask-size: contain;
  mask-size: contain;
  -webkit-mask-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23000' stroke-width='2.2' stroke-linecap='round' stroke-linejoin='round'><path d='M15 18l-6-6 6-6'/></svg>");
  mask-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23000' stroke-width='2.2' stroke-linecap='round' stroke-linejoin='round'><path d='M15 18l-6-6 6-6'/></svg>");
}

/* 标题部分 */
.glass-header:has(.header-profile-section) .header-profile-section {
  display: flex !important;
  align-items: center !important;
  margin-left: 8px !important; /* ❎ 标题距离返回键的左边距：8px 越大越往右 */
  transform: translateY(2px) !important; /* ❎ 标题上下位置：2px 越大越往下，负数越往上 */
}

.glass-header:has(.header-profile-section) .chat-header-title {
  color: var(--header-text-main) !important;
  -webkit-text-fill-color: var(--header-text-main) !important;
  font-size: 16.5px !important;
  font-weight: 600 !important;
  letter-spacing: -0.2px !important;
}

/* 隐藏副标题 */
.glass-header:has(.header-profile-section) .chat-header-subtitle {
  display: none !important;
}

/* 装饰区域：三段式标签 */
.glass-header:has(.header-profile-section)::after {
  content: "Nearby       Following       Explore";
  position: absolute !important;
  left: var(--tab-offset-left) !important; /* ❎ 标签栏左偏移，在全局变量里控制（当前45px） */
  bottom: 0px !important; /* ❎ 标签栏底部位置：0px 越大越往上 */
  height: 28px !important;
  line-height: 20px !important;
  font-size: var(--tab-font-size) !important;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif !important;
  font-style: normal !important;
  font-weight: 500 !important;
  letter-spacing: 0.3px !important;
  white-space: pre !important;
  pointer-events: none !important;
  color: var(--tab-color-inactive) !important;
  background-image: 
    linear-gradient(var(--tab-indicator-color), var(--tab-indicator-color)),
    linear-gradient(var(--tab-color-active), var(--tab-color-active));
  background-size: 44px 2px, 46px 100% !important;
  background-position: 0 bottom, 0 top !important;
  background-repeat: no-repeat !important;
  -webkit-background-clip: border-box, text !important;
  background-clip: border-box, text !important;
}

/* 电话与视频按钮保留透明点击区 */
.glass-header:has(.header-profile-section) .header-btn-phone,
.glass-header:has(.header-profile-section) .header-btn-video {
  opacity: 0 !important;
  pointer-events: auto !important;
  margin-right: 6px !important; /* ❎ 电话/视频按钮右边距：6px */
  transform: translateY(2px) !important; /* ❎ 电话/视频按钮上下位置：2px */
}

/* 右侧大头像改造 */
#chat-detail-screen .header-btn-info {
  width: var(--header-avatar-size) !important;
  height: var(--header-avatar-size) !important;
  border-radius: 50% !important;
  clip-path: circle(50% at 50% 50%) !important;
  -webkit-clip-path: circle(50% at 50% 50%) !important;
  background-color: transparent !important;
  background-image: var(--header-avatar-img) !important;
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  box-shadow: none !important;
  border: none !important;
  outline: none !important;
  transform: translateY(0px) !important; /* ❎ 右侧大头像上下位置：0px 越大越往下，负数越往上 */
  flex-shrink: 0 !important;
  cursor: pointer !important;
}

/* 隐藏原本 info 键自带的图标 */
#chat-detail-screen .header-btn-info svg {
  display: none !important;
}

/* ==========================================================================
   第二部分：底部 (Footer)
   ========================================================================== */

/* 底栏外层大背景：与全局主背景色同步贯通 */
.input-area-custom,
div:has(> .input-row-wrapper) {
  background: var(--custom-input-bg) !important;
  border-top: none !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
